#!/usr/bin/env bash
# =============================================================================
#  OwnCurve — script de trabajo (se sobreescribe en cada entrega)
#  Fase actual: F2  Núcleo on-chain + tests   (no gasta SOL: todo es local)
#    2.1 cobro completo a la tesorería: comisiones de trading, excedente y LP de DAMM v2
#    2.2 config DBC + init_raise atómicos (ya en el cliente)
#    2.3 entorno de tests: LiteSVM con los binarios reales de DBC y DAMM v2
#    2.4–2.6 17 tests: flujo feliz, rechazo/liquidación/redención, ataques
#    + reglas anti-rug nuevas en bind_pool / init_raise
#
#  Uso:   cd ~/owncurve && bash owncurve.sh
#  Log completo: ~/owncurve/logs/F2.log
# =============================================================================
set -Eeuo pipefail

PHASE="F2"
REPO_DIR="$HOME/owncurve"
DBC_REV="f552f20aa3c1c7631427c3827aeea7c58b902813"
LOG_DIR="$REPO_DIR/logs"
mkdir -p "$LOG_DIR"
LOG="$LOG_DIR/$PHASE.log"
: > "$LOG"

G='\033[1;32m'; R='\033[1;31m'; Y='\033[1;33m'; B='\033[1;34m'; N='\033[0m'
ok()   { echo -e "${G}  ✔ $*${N}"; }
warn() { echo -e "${Y}  ! $*${N}"; }
fail() { echo -e "${R}  ✘ $*${N}"; echo -e "${R}    Revisa el log: $LOG${N}"; exit 1; }
step() { echo -e "\n${B}==> $*${N}"; }
run()  {
  local desc="$1"; shift
  echo "+ $*" >> "$LOG"
  if "$@" >> "$LOG" 2>&1; then ok "$desc"; else fail "$desc"; fi
}
trap 'echo -e "${R}Error inesperado en la línea $LINENO. Log: $LOG${N}"' ERR

[ -f "$HOME/.cargo/env" ] && . "$HOME/.cargo/env"
export PATH="$HOME/.local/share/solana/install/active_release/bin:$HOME/.avm/bin:$PATH"

echo -e "${B}OwnCurve · $PHASE · $(date '+%Y-%m-%d %H:%M')${N}"

# =============================================================================
step "1/6 Comprobaciones"
# =============================================================================
for t in solana anchor cargo cargo-build-sbf node npm jq git; do
  command -v "$t" >/dev/null 2>&1 || fail "Falta '$t'. ¿Completaste F1.1? (abre una terminal nueva o 'source ~/.zshrc')"
done
[ -f "$REPO_DIR/target/deploy/owncurve-keypair.json" ] || fail "Falta la clave del programa. Ejecuta primero F1.1"
ok "Herramientas listas · $(anchor --version) · node $(node -v)"
cd "$REPO_DIR"

# =============================================================================
step "2/6 Código actualizado (programa, cliente, tests)"
# =============================================================================
cat > '.gitignore' <<'OWNCURVE_EOF'
target/
logs/
node_modules/
.anchor/
test-ledger/
.owncurve/
local/
.deps/
OWNCURVE_EOF

cat > 'Cargo.lock' <<'OWNCURVE_EOF'
